const fs = require('fs');
const path = require('path');

// Minimal 1x1 transparent PNG (base64)
const transparentPng = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==',
  'base64'
);

// Simple dark colored 512x512 PNG (solid color placeholder)
// This is a minimal valid PNG with a dark purple color (#BB86FC background)
const iconPngBase64 = '';

const assetsDir = path.join(__dirname, '..', 'assets');

// Ensure assets directory exists
if (!fs.existsSync(assetsDir)) {
  fs.mkdirSync(assetsDir, { recursive: true });
}

// Create placeholder icons
const iconBuffer = Buffer.from(iconPngBase64, 'base64');

fs.writeFileSync(path.join(assetsDir, 'icon.png'), iconBuffer);
fs.writeFileSync(path.join(assetsDir, 'adaptive-icon.png'), iconBuffer);
fs.writeFileSync(path.join(assetsDir, 'splash-icon.png'), iconBuffer);
fs.writeFileSync(path.join(assetsDir, 'favicon.png'), iconBuffer);

console.log('Assets generated successfully!');
